export function resolveExerciseAlias(spoken) {
  const k = String(spoken || '').toLowerCase().replace(/\s+/g, ' ').trim()
  if (!k) return null
  return ALIAS_TO_CANONICAL[k] || ALIAS_TO_CANONICAL[k.replace(/[’']/g, '')] || null
}
